  - claims.8.entity: must have required properties entity, attribute, value, quote

Received arguments:
{
  "claims": [
    {
      "attribute": "porch_description",
      "entity": "loc-halloway-house",
      "quote": "\"A tidy blue door set on a low porch where ferns droop in green pots; the porch boards smell of lemon oil and old tea.\"",
      "value": "loc-halloway-house porch has a tidy blue door, ferns in green pots, and porch boards that smell of lemon oil and old tea."
    },
    {
      "attribute": "halloway_acceptance",
      "entity": "char-mrs-halloway",
      "quote": "\"Oh my—it's home. Thank you, darling. Some things like to be put back where they belong,\" she says, and my knees go light.",
      "value": "Mrs. Halloway accepted the returned brooch and remarked that some things like to be put back where they belong."
    },
    {
      "attribute": "halloway_brooch_story",
      "entity": "char-mrs-halloway",
      "quote": "\"This brooch belonged to my mother. She wore it when she forgave someone she thought she could never forgive — and it somehow reminded her that courage could be small and steady, like returning a thing where it ought to be.\"",
      "value": "Mrs. Halloway explained the brooch's history and its meaning about small, steady courage."
    },
    {
      "attribute": "halloway_giving_line",
      "entity": "char-mrs-halloway",
      "quote": "\"You two have more courage than you know. Take this — a stamped token from my knitting group. For when you need to remember today.\"",
      "value": "Mrs. Halloway gave the children a small stamped token from her knitting group as a keepsake."
    },
    {
      "attribute": "keepsake_description",
      "entity": "obj-unknown",
      "quote": "She presses a small brass coin into my hand; it's stamped with a clumsy thimble and worn smooth at the edges. It fits in my palm like a secret.",
      "value": "a small brass token stamped with a clumsy thimble, worn smooth at the edges, given as a keepsake."
    },
    {
      "attribute": "milo_conciliatory",
      "entity": "char-milo",
      "quote": "He digs into his pocket and scuffs something into our hands — a damp, scuffed toy car — and mutters, \"Sorry. Here.\"",
      "value": "Milo offered a damp, scuffed toy car and said 'Sorry. Here.' as a conciliatory gesture."
    },
    {
      "attribute": "brooch_returned",
      "entity": "obj-brooch",
      "quote": "I hold the brooch out on my palm like an offering. Her fingers hover and then close around it with a gentleness that surprises me.",
      "value": "char-mrs-halloway"
    },
    {
      "attribute": "lunchbox_returned",
      "entity": "obj-lunchbox",
      "quote": "Jun nudges his backpack forward and I put the tin into her hands.",
      "value": "char-mrs-halloway"
    },
    {
      "{": "malformed"
    }
  ],
